<script>(()=>{document.querySelectorAll('.lab').forEach(lab=>{const examples=JSON.parse(lab.dataset.examples),code=lab.querySelector('.lab-code'),input=lab.querySelector('.lab-input'),output=lab.querySelector('.lab-output'),tabs=[...lab.querySelectorAll('.language-tab')];let language=tabs[0]?.dataset.language;const select=next=>{language=next;tabs.forEach(tab=>tab.classList.toggle('active',tab.dataset.language===next));code.value=examples[next].code};tabs.forEach(tab=>tab.addEventListener('click',()=>select(tab.dataset.language)));lab.querySelector('.lab-run').addEventListener('click',()=>{const values=input.value.split(/\r?\n/);if(values.length<4||!values[0].trim()||Number.isNaN(Number(values[1]))||Number.isNaN(Number(values[2]))||!values[3].trim()){output.textContent='Input error: use four lines — name, age, height and grade.';return}output.textContent='----- Student Details -----\nName: '+values[0].trim()+'\nAge: '+Number(values[1])+'\nHeight: '+Number(values[2])+'\nGrade: '+values[3].trim().charAt(0);});if(language)select(language)})})();</script>
