<script>(()=>{const key='ascendia_spring_{{$moduleSlug}}',done=new Set(JSON.parse(localStorage.getItem(key)||'[]')),score=document.querySelector('#score'),bar=document.querySelector('#progress'),total={{count($lessons)}};const paint=()=>{score.textContent=done.size;bar.style.width=(done.size/total*100)+'%'};paint();document.querySelectorAll('.quiz').forEach(quiz=>{const feedback=quiz.querySelector('.feedback'),answer=Number(quiz.dataset.answer);quiz.querySelectorAll('.option').forEach(button=>button.addEventListener('click',()=>{quiz.querySelectorAll('.option').forEach(option=>{option.disabled=true;if(Number(option.dataset.option)===answer)option.classList.add('correct')});const correct=Number(button.dataset.option)===answer;if(!correct)button.classList.add('wrong');feedback.className='feedback show '+(correct?'good':'bad');feedback.textContent=(correct?'Correct! ':'Not quite. ')+quiz.dataset.why;if(correct){done.add(Number(quiz.dataset.lesson));localStorage.setItem(key,JSON.stringify([...done]));paint()}}))});document.querySelectorAll('.copy').forEach(button=>button.addEventListener('click',async()=>{await navigator.clipboard.writeText(button.closest('.body').querySelector('code').textContent);button.textContent='Copied!';setTimeout(()=>button.textContent='Copy code',1200)}))})();</script>
